{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2184-08-17 21:30:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee, one of your surgical team. I know you’ve been having severe abdominal pain and nausea. Can you tell me more about what brought you in?"
    },
    {
      "turn_number": 2,
      "time": "2184-08-17 21:31:00",
      "speaker": "Patient",
      "text": "Yes, I’ve had terrible cramping for two days—no bowel movements, no gas. I couldn’t keep anything down, not even through my tube. It felt worse than usual."
    },
    {
      "turn_number": 3,
      "time": "2184-08-17 21:32:00",
      "speaker": "Doctor",
      "text": "I see. You have a history of gastroparesis and a feeding tube. We did a CT scan, and it showed something serious—your cecum, part of your colon, has twisted. That’s called a cecal volvulus."
    },
    {
      "turn_number": 4,
      "time": "2184-08-17 21:33:00",
      "speaker": "Patient",
      "text": "Twisted? Is that why I couldn’t pass anything?"
    },
    {
      "turn_number": 5,
      "time": "2184-08-17 21:34:00",
      "speaker": "Doctor",
      "text": "Exactly. The twist is blocking your bowel. Worse, the blood supply is compromised—there’s early signs of ischemia. This needs surgery, and soon."
    },
    {
      "turn_number": 6,
      "time": "2184-08-17 21:35:00",
      "speaker": "Patient",
      "text": "Surgery? Again? I’ve had so many… What kind of surgery?"
    },
    {
      "turn_number": 7,
      "time": "2184-08-17 21:36:00",
      "speaker": "Doctor",
      "text": "We’ll do an exploratory laparotomy. We’ll remove the twisted part of your colon—the right side—and reconnect your intestine. There’s also something else."
    },
    {
      "turn_number": 8,
      "time": "2184-08-17 21:37:00",
      "speaker": "Patient",
      "text": "What else?"
    },
    {
      "turn_number": 9,
      "time": "2184-08-17 21:38:00",
      "speaker": "Doctor",
      "text": "The CT suggests the wires from your old gastric pacemaker may have caused the twist. They’re looping into your bowel. We’ll remove the device and wires during the surgery."
    },
    {
      "turn_number": 10,
      "time": "2184-08-17 21:39:00",
      "speaker": "Patient",
      "text": "Oh… I forgot I even had that pacemaker. Is it dangerous to remove?"
    },
    {
      "turn_number": 11,
      "time": "2184-08-17 21:40:00",
      "speaker": "Doctor",
      "text": "It’s safe, and necessary. Leaving it could cause more problems. We’ve discussed this with your family, and we have your consent. We’ll prepare you for the OR now."
    },
    {
      "turn_number": 12,
      "time": "2184-08-18 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You made it through surgery. You had a right hemicolectomy and the pacemaker with its wires was removed. The anastomosis looks good."
    },
    {
      "turn_number": 13,
      "time": "2184-08-18 08:01:00",
      "speaker": "Patient",
      "text": "How do I feel? I’m so groggy… Was everything okay?"
    },
    {
      "turn_number": 14,
      "time": "2184-08-18 08:02:00",
      "speaker": "Doctor",
      "text": "The surgery went well—no complications. You’re on a PCA pump for pain. You have an NG tube for now, and we’re giving fluids and antibiotics through your IV."
    },
    {
      "turn_number": 15,
      "time": "2184-08-18 08:03:00",
      "speaker": "Patient",
      "text": "Will I be able to eat soon?"
    },
    {
      "turn_number": 16,
      "time": "2184-08-18 08:04:00",
      "speaker": "Doctor",
      "text": "Not yet. We need to wait for your bowel to wake up. We’ll start tube feeds once we hear bowel sounds and you pass gas."
    },
    {
      "turn_number": 17,
      "time": "2184-08-19 07:45:00",
      "speaker": "Doctor",
      "text": "Good news—your NG tube is out. You’re passing gas, and your belly is less distended. We’ll keep you NPO for now, but we’re close to starting feeds."
    },
    {
      "turn_number": 18,
      "time": "2184-08-19 07:46:00",
      "speaker": "Patient",
      "text": "That’s a relief. My throat was so sore from the tube."
    },
    {
      "turn_number": 19,
      "time": "2184-08-20 08:00:00",
      "speaker": "Doctor",
      "text": "Your white count was high but is coming down. That means the infection risk is improving. We’re still holding off on feeds—just a little longer."
    },
    {
      "turn_number": 20,
      "time": "2184-08-21 07:50:00",
      "speaker": "Doctor",
      "text": "We’re going to start your tube feeds today—slowly, at half goal. We’ll monitor for nausea or bloating."
    },
    {
      "turn_number": 21,
      "time": "2184-08-21 07:51:00",
      "speaker": "Patient",
      "text": "Okay, but I’m still feeling a bit nauseous. Is that normal?"
    },
    {
      "turn_number": 22,
      "time": "2184-08-21 07:52:00",
      "speaker": "Doctor",
      "text": "Yes, especially after surgery and with your history. We’ll give you anti-nausea meds and go slow. If you tolerate this, we’ll increase tomorrow."
    },
    {
      "turn_number": 23,
      "time": "2184-08-22 08:10:00",
      "speaker": "Doctor",
      "text": "You’re doing well with the feeds. We’re increasing to full rate. Your labs are stable, and you’re walking more each day."
    },
    {
      "turn_number": 24,
      "time": "2184-08-23 10:00:00",
      "speaker": "Doctor",
      "text": "Today, we’re exchanging your GJ tube to one with separate G and J ports. It’ll give us more flexibility with feeding and meds."
    },
    {
      "turn_number": 25,
      "time": "2184-08-23 10:01:00",
      "speaker": "Patient",
      "text": "Is that a big procedure?"
    },
    {
      "turn_number": 26,
      "time": "2184-08-23 10:02:00",
      "speaker": "Doctor",
      "text": "No, it’s done endoscopically with light sedation. You’ll be back soon, and we’ll restart feeds through the new tube."
    },
    {
      "turn_number": 27,
      "time": "2184-08-23 16:00:00",
      "speaker": "Doctor",
      "text": "The tube exchange went smoothly. You’re back on full feeds. How are you feeling?"
    },
    {
      "turn_number": 28,
      "time": "2184-08-23 16:01:00",
      "speaker": "Patient",
      "text": "A bit sore at the site, but okay. Still nauseous when I try to eat by mouth."
    },
    {
      "turn_number": 29,
      "time": "2184-08-24 08:00:00",
      "speaker": "Doctor",
      "text": "We expected that. We’re going to try clamping your tube for short periods to see if you can tolerate oral intake."
    },
    {
      "turn_number": 30,
      "time": "2184-08-24 08:01:00",
      "speaker": "Patient",
      "text": "But I’ve always had trouble keeping food down."
    },
    {
      "turn_number": 31,
      "time": "2184-08-24 08:02:00",
      "speaker": "Doctor",
      "text": "Yes, but we need to assess if it’s mechanical or motility-related. We’ll schedule a gastric emptying study."
    },
    {
      "turn_number": 32,
      "time": "2184-08-25 09:00:00",
      "speaker": "Doctor",
      "text": "Your gastric emptying study came back normal. Liquids are leaving your stomach at a normal rate."
    },
    {
      "turn_number": 33,
      "time": "2184-08-25 09:01:00",
      "speaker": "Patient",
      "text": "Then why do I feel so full and nauseous?"
    },
    {
      "turn_number": 34,
      "time": "2184-08-25 09:02:00",
      "speaker": "Doctor",
      "text": "We did an upper GI study too. It shows your Nissen fundoplication is intact, no narrowing. But there’s moderate esophageal dysmotility—your esophagus isn’t moving food down well."
    },
    {
      "turn_number": 35,
      "time": "2184-08-25 09:03:00",
      "speaker": "Patient",
      "text": "So it’s not my stomach, it’s my esophagus?"
    },
    {
      "turn_number": 36,
      "time": "2184-08-25 09:04:00",
      "speaker": "Doctor",
      "text": "Exactly. That explains the nausea when you try to eat. We’ll adjust your diet and add a new anti-nausea med. You’ll follow up with GI after discharge."
    },
    {
      "turn_number": 37,
      "time": "2184-08-26 08:00:00",
      "speaker": "Doctor",
      "text": "You’re tolerating clamping trials better. We’re advancing your diet to regular food in small amounts."
    },
    {
      "turn_number": 38,
      "time": "2184-08-26 08:01:00",
      "speaker": "Patient",
      "text": "I had a few bites yesterday and didn’t vomit. That’s progress!"
    },
    {
      "turn_number": 39,
      "time": "2184-08-27 07:50:00",
      "speaker": "Doctor",
      "text": "Great. Your incision is healing well—no redness or drainage. Pain is controlled with oral meds now."
    },
    {
      "turn_number": 40,
      "time": "2184-08-27 07:51:00",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 41,
      "time": "2184-08-27 07:52:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow. You’re walking independently, tolerating a regular diet, and your feeds are at goal."
    },
    {
      "turn_number": 42,
      "time": "2184-08-28 08:00:00",
      "speaker": "Doctor",
      "text": "Final check: your labs are stable, vitals are good. Home health will help with your GJ tube and feeds."
    },
    {
      "turn_number": 43,
      "time": "2184-08-28 08:01:00",
      "speaker": "Patient",
      "text": "What about my meds?"
    },
    {
      "turn_number": 44,
      "time": "2184-08-28 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll continue levothyroxine, citalopram, omeprazole. We’re adding dronabinol and trimethobenzamide for nausea, as needed."
    },
    {
      "turn_number": 45,
      "time": "2184-08-28 08:03:00",
      "speaker": "Patient",
      "text": "And my follow-up?"
    },
    {
      "turn_number": 46,
      "time": "2184-08-28 08:04:00",
      "speaker": "Doctor",
      "text": "See your surgeon in two weeks. GI will evaluate your esophageal dysmotility. Call us if you have fever, vomiting, or incision problems."
    },
    {
      "turn_number": 47,
      "time": "2184-08-28 08:05:00",
      "speaker": "Patient",
      "text": "What about lifting or driving?"
    },
    {
      "turn_number": 48,
      "time": "2184-08-28 08:06:00",
      "speaker": "Doctor",
      "text": "No lifting over five pounds for four weeks. Don’t drive while on pain meds. Showering is okay—just keep the incision dry."
    },
    {
      "turn_number": 49,
      "time": "2184-08-28 08:07:00",
      "speaker": "Patient",
      "text": "And the steri-strips?"
    },
    {
      "turn_number": 50,
      "time": "2184-08-28 08:08:00",
      "speaker": "Doctor",
      "text": "They’ll fall off on their own. Remove any left after ten days. Staples will be removed at your follow-up."
    },
    {
      "turn_number": 51,
      "time": "2184-08-28 08:09:00",
      "speaker": "Patient",
      "text": "I’m nervous about managing the tube at home."
    },
    {
      "turn_number": 52,
      "time": "2184-08-28 08:10:00",
      "speaker": "Doctor",
      "text": "Home health will train you and your caregiver. They’ll visit several times a week at first. You’re not alone in this."
    },
    {
      "turn_number": 53,
      "time": "2184-08-28 08:11:00",
      "speaker": "Patient",
      "text": "Thank you. I feel more confident now."
    },
    {
      "turn_number": 54,
      "time": "2184-08-28 08:12:00",
      "speaker": "Doctor",
      "text": "You’ve worked hard. Keep resting, stay hydrated, and keep walking. You’re on the mend."
    },
    {
      "turn_number": 55,
      "time": "2184-08-29 09:00:00",
      "speaker": "Doctor",
      "text": "All set for discharge. Your condition is stable, you’re tolerating everything well. We’re proud of your progress."
    },
    {
      "turn_number": 56,
      "time": "2184-08-29 09:01:00",
      "speaker": "Patient",
      "text": "I can’t wait to be home. Thank you for everything."
    },
    {
      "turn_number": 57,
      "time": "2184-08-29 09:02:00",
      "speaker": "Doctor",
      "text": "We’ll be here if you need us. Take care, and see you soon in clinic."
    },
    {
      "turn_number": 58,
      "time": "2184-08-29 09:03:00",
      "speaker": "Patient",
      "text": "One last thing—should I get the flu shot this year?"
    },
    {
      "turn_number": 59,
      "time": "2184-08-29 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, absolutely. It’s especially important with your medical history. Your primary care can give it in a few weeks."
    },
    {
      "turn_number": 60,
      "time": "2184-08-29 09:05:00",
      "speaker": "Patient",
      "text": "Good to know. I’ll schedule it."
    },
    {
      "turn_number": 61,
      "time": "2184-08-29 09:06:00",
      "speaker": "Doctor",
      "text": "Perfect. Rest well, and don’t hesitate to call with any concerns."
    },
    {
      "turn_number": 62,
      "time": "2184-08-29 09:07:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 63,
      "time": "2184-08-29 09:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take it one day at a time."
    },
    {
      "turn_number": 64,
      "time": "2184-08-29 09:09:00",
      "speaker": "Patient",
      "text": "I’ve learned that the hard way."
    },
    {
      "turn_number": 65,
      "time": "2184-08-29 09:10:00",
      "speaker": "Doctor",
      "text": "And you’re doing great. Keep it up."
    },
    {
      "turn_number": 66,
      "time": "2184-08-29 09:11:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 67,
      "time": "2184-08-29 09:12:00",
      "speaker": "Doctor",
      "text": "Nurse will bring your discharge papers and meds shortly."
    },
    {
      "turn_number": 68,
      "time": "2184-08-29 09:13:00",
      "speaker": "Patient",
      "text": "Okay, I’ll review them carefully."
    },
    {
      "turn_number": 69,
      "time": "2184-08-29 09:14:00",
      "speaker": "Doctor",
      "text": "Good idea. Call us if anything’s unclear."
    },
    {
      "turn_number": 70,
      "time": "2184-08-29 09:15:00",
      "speaker": "Patient",
      "text": "I will. Thank you for being so thorough."
    },
    {
      "turn_number": 71,
      "time": "2184-08-29 09:16:00",
      "speaker": "Doctor",
      "text": "It’s our job. You’ve been a great patient—cooperative and strong."
    },
    {
      "turn_number": 72,
      "time": "2184-08-29 09:17:00",
      "speaker": "Patient",
      "text": "It’s been a lot, but I’m glad it’s over."
    },
    {
      "turn_number": 73,
      "time": "2184-08-29 09:18:00",
      "speaker": "Doctor",
      "text": "And you came through it well. Recovery will take time, but you’re on the right path."
    },
    {
      "turn_number": 74,
      "time": "2184-08-29 09:19:00",
      "speaker": "Patient",
      "text": "I’ll take it slow."
    },
    {
      "turn_number": 75,
      "time": "2184-08-29 09:20:00",
      "speaker": "Doctor",
      "text": "That’s the best plan. See you soon."
    },
    {
      "turn_number": 76,
      "time": "2184-08-29 09:21:00",
      "speaker": "Patient",
      "text": "See you."
    },
    {
      "turn_number": 77,
      "time": "2184-08-29 09:22:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 78,
      "time": "2184-08-29 09:23:00",
      "speaker": "Patient",
      "text": "You too."
    },
    {
      "turn_number": 79,
      "time": "2184-08-29 09:24:00",
      "speaker": "Doctor",
      "text": "Nurse will be in shortly."
    },
    {
      "turn_number": 80,
      "time": "2184-08-29 09:25:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready."
    },
    {
      "turn_number": 81,
      "time": "2184-08-29 09:26:00",
      "speaker": "Doctor",
      "text": "We’ll miss you, but we’re glad you’re going home."
    },
    {
      "turn_number": 82,
      "time": "2184-08-29 09:27:00",
      "speaker": "Patient",
      "text": "I’ll miss you all too. Thanks for taking care of me."
    },
    {
      "turn_number": 83,
      "time": "2184-08-29 09:28:00",
      "speaker": "Doctor",
      "text": "It’s been our privilege. Get some rest at home."
    },
    {
      "turn_number": 84,
      "time": "2184-08-29 09:29:00",
      "speaker": "Patient",
      "text": "I will. Goodbye for now."
    },
    {
      "turn_number": 85,
      "time": "2184-08-29 09:30:00",
      "speaker": "Doctor",
      "text": "Goodbye. Take care."
    }
  ],
  "summary": {
    "admission_start": "2184-08-17 21:25:00",
    "admission_end": "2184-08-29 12:35:00",
    "summary_paragraph": "A woman with a history of gastroparesis, gastrostomy, and a gastric pacemaker was admitted for severe abdominal pain and vomiting. Imaging revealed cecal volvulus with ischemia, likely caused by entanglement of the bowel with the pacemaker wires. She underwent an exploratory laparotomy, right hemicolectomy, ileotransverse anastomosis, stomach repair, and removal of the gastric pacemaker and wires. Postoperatively, she had ongoing nausea and difficulty tolerating oral intake, but gradually improved with tube feeds and diet advancement. A gastric emptying study was normal, but an upper GI series showed moderate esophageal dysmotility. She tolerated a regular diet and full tube feeds by discharge, with stable vital signs and healing incisions. She was discharged home with home health services for GJ tube care and follow-up with gastroenterology for esophageal evaluation.",
    "problems": [
      "Volvulus",
      "Unspecified vascular insufficiency of intestine",
      "Gastroparesis",
      "Gastrostomy status",
      "Esophageal reflux",
      "Unspecified acquired hypothyroidism",
      "Depressive disorder, not elsewhere classified",
      "Anxiety state, unspecified",
      "Personal history of malignant neoplasm of breast",
      "Irritable bowel syndrome",
      "Osteoporosis, unspecified",
      "Adhesive capsulitis of shoulder",
      "Personal history of other malignant neoplasm of skin",
      "Unspecified vitamin D deficiency",
      "Need for prophylactic vaccination and inoculation against influenza"
    ]
  }
}
